", "lru.test.mjs": "import assert from "node:assert/strict";
import { LRUCache } from "./lru.js";

// deterministic PRNG (mulberry32, seed 42) for the stress test
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// naive reference LRU: array of [key, value]; index 0 = LRU, last = MRU
class RefLRU {
  constructor(capacity) { this.cap = capacity; this.items = []; }
  get(key) {
    const i = this.items.findIndex(([k]) => k === key);
    if (i === -1) return -1;
    const e = this.items.splice(i, 1)[0];
    this.items.push(e);
    return e[1];
  }
  put(key, value) {
    const i = this.items.findIndex(([k]) => k === key);
    if (i !== -1) this.items.splice(i, 1);
    this.items.push([key, value]);
    if (this.items.length > this.cap) this.items.shift();
  }
}

// --- capacity 2: eviction order with interleaved gets ---
{
  const c = new LRUCache(2);
  c.put(1, 1);
  c.put(2, 2);
  assert.equal(c.get(1), 1);       // 1 becomes MRU
  c.put(3, 3);                     // evicts 2 (LRU)
  assert.equal(c.get(2), -1, "key 2 should have been evicted");
  assert.equal(c.get(3), 3);
  c.put(4, 4);                     // evicts 1
  assert.equal(c.get(1), -1, "key 1 should have been evicted");
  assert.equal(c.get(3), 3);
  assert.equal(c.get(4), 4);
}

// --- get refreshes recency: without the get, the OTHER key is evicted ---
{
  const c = new LRUCache(2);
  c.put("a", 1);
  c.put("b", 2);
  c.get("a");                      // a is MRU now
  c.put("c", 3);                   // evicts b
  assert.equal(c.get("b"), -1, "b (LRU) should have been evicted");
  assert.equal(c.get("a"), 1);
  assert.equal(c.get("c"), 3);
}

// --- updating an existing key must NOT evict anything ---
{
  const c = new LRUCache(2);
  c.put(1, 1);
  c.put(2, 2);
  c.put(1, 10);                    // update in place, no capacity change
  assert.equal(c.get(1), 10, "updated value must be returned");
  c.put(3, 3);                     // evicts 2 (1 was refreshed by the put)
  assert.equal(c.get(2), -1, "2 should have been evicted (1 was refreshed)");
  assert.equal(c.get(1), 10);
}

// --- get of a missing key returns -1 and does not disturb state ---
{
  const c = new LRUCache(2);
  assert.equal(c.get(42), -1, "missing key must return -1");
  c.put(42, "x");
  assert.equal(c.get(43), -1);
  assert.equal(c.get(42), "x");
}

// --- capacity 1 edge case ---
{
  const c = new LRUCache(1);
  c.put(1, 1);
  assert.equal(c.get(1), 1);
  c.put(2, 2);                     // evicts 1
  assert.equal(c.get(1), -1, "capacity-1 must evict on the second put");
  assert.equal(c.get(2), 2);
  c.put(2, 22);                    // update in place, still just key 2
  assert.equal(c.get(2), 22);
  assert.equal(c.get(1), -1);
}

// --- string keys and mixed value types behave like any other key ---
{
  const c = new LRUCache(3);
  c.put("x", { id: 1 });
  c.put("y", [1, 2]);
  c.put("z", "s");
  assert.deepEqual(c.get("x"), { id: 1 });
  c.put("w", 9);                   // evicts y (LRU)
  assert.equal(c.get("y"), -1);
  assert.equal(c.get("z"), "s");
  assert.equal(c.get("w"), 9);
}

// --- 500-op randomized stress test against the reference implementation ---
{
  const rand = mulberry32(42);
  const real = new LRUCache(4);
  const ref = new RefLRU(4);
  const history = [];
  for (let op = 0; op < 500; op++) {
    const key = Math.floor(rand() * 8);   // keys 0..7 vs capacity 4: constant churn
    const isPut = rand() < 0.55;
    history.push((isPut ? "put:" : "get:") + key);
    if (isPut) {
      const value = op * 3 + 1;
      real.put(key, value);
      ref.put(key, value);
    } else {
      assert.equal(
        real.get(key),
        ref.get(key),
        "op #" + op + " get(" + key + ") diverged; recent ops: " + history.slice(-8).join(" ")
      );
    }
  }
  for (let k = 0; k < 8; k++) {
    assert.equal(real.get(k), ref.get(k), "final state diverged for key " + k);
  }
}

console.log("lru tests passed");
"}

