  for (let i = 0; i < n; i++) {
    store.value = store.value + 1;
  }
}
", "counter.test.mjs": "import assert from "node:assert/strict";
import { incrementN } from "./counter.js";

// FakeStore: writes are deferred onto the microtask queue and reads are
// asynchronous (the getter hands back a Promise). A plain synchronous
// read-modify-write therefore reads a Promise object and loses updates.
class FakeStore {
  constructor() {
    this._v = 0;
    this.pendingSets = 0;
    this.maxPendingSets = 0;
  }
  get value() {
    // async get: callers must await; a sync read sees a Promise object
    return Promise.resolve(this._v);
  }
  set value(v) {
    this.pendingSets++;
    if (this.pendingSets > this.maxPendingSets) this.maxPendingSets = this.pendingSets;
    queueMicrotask(() => {
      this.pendingSets--;
      this._v = v;
    });
  }
}

// --- correctness from zero ---
{
  const s = new FakeStore();
  await incrementN(s, 50);
  assert.equal(await s.value, 50, "final value must be exactly n (50)");
}

// --- correctness from a non-zero start ---
{
  const s = new FakeStore();
  s.value = 7;            // pre-seed through the public interface
  await s.value;          // let the seed write land
  assert.equal(await s.value, 7, "precondition: store starts at 7");
  await incrementN(s, 20);
  assert.equal(await s.value, 27, "final value must be start + n (7 + 20)");
}

// --- overlap: increments must not run strictly sequentially ---
{
  const s = new FakeStore();
  await incrementN(s, 50);
  assert.ok(
    s.maxPendingSets > 1,
    "increments must overlap: expected more than 1 concurrent pending write at some point, saw max=" + s.maxPendingSets
  );
}

console.log("counter tests passed");
"}

